import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"0. Overview and Design Contract","description":"","frontmatter":{},"headers":[],"relativePath":"spec/00-overview.md","filePath":"spec/00-overview.md","lastUpdated":null}'),o={name:"spec/00-overview.md"};function r(s,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="_0-overview-and-design-contract" tabindex="-1">0. Overview and Design Contract <a class="header-anchor" href="#_0-overview-and-design-contract" aria-label="Permalink to &quot;0. Overview and Design Contract&quot;">​</a></h1><h2 id="_0-1-purpose" tabindex="-1">0.1 Purpose <a class="header-anchor" href="#_0-1-purpose" aria-label="Permalink to &quot;0.1 Purpose&quot;">​</a></h2><p>Linnet is a statically typed declarative tensor language. A <code>.linnet</code> file describes tensor computation and model structure without embedding tensor payloads or arbitrary host-language code.</p><p>The language is intended to be:</p><ul><li>directly authored by humans;</li><li>suitable as a durable, reviewable model artifact;</li><li>statically checked before weights are loaded;</li><li>portable across execution frameworks and compiler IRs;</li><li>optimizable without requiring model-specific compiler changes.</li></ul><h2 id="_0-2-architectural-invariants" tabindex="-1">0.2 Architectural invariants <a class="header-anchor" href="#_0-2-architectural-invariants" aria-label="Permalink to &quot;0.2 Architectural invariants&quot;">​</a></h2><p>The following rules are normative design constraints for the implementation.</p><h3 id="a-model-independence" tabindex="-1">A. Model independence <a class="header-anchor" href="#a-model-independence" aria-label="Permalink to &quot;A. Model independence&quot;">​</a></h3><p>The compiler core MUST NOT contain model-specific names such as <code>Llama</code>, <code>Qwen</code>, <code>Gemma</code>, or equivalent architecture identifiers.</p><h3 id="b-library-defined-semantic-operations" tabindex="-1">B. Library-defined semantic operations <a class="header-anchor" href="#b-library-defined-semantic-operations" aria-label="Permalink to &quot;B. Library-defined semantic operations&quot;">​</a></h3><p>High-level operations such as <code>linear</code>, <code>rope</code>, <code>rms_norm</code>, <code>attention</code>, <code>conv</code>, and <code>moe</code> SHOULD be implemented as Linnet <code>op</code> declarations in <code>.linnet</code> libraries. They MUST NOT require compiler modifications unless the operation fundamentally cannot be expressed with the existing primitive tensor algebra.</p><h3 id="c-primitive-fallback" tabindex="-1">C. Primitive fallback <a class="header-anchor" href="#c-primitive-fallback" aria-label="Permalink to &quot;C. Primitive fallback&quot;">​</a></h3><p>Every non-extern semantic <code>op</code> MUST have a valid body defining its canonical semantics in lower-level Linnet operations. A backend MAY replace an <code>op</code> or a recognized decomposition with a native implementation, but correctness MUST NOT depend on such a replacement.</p><h3 id="d-weight-separation" tabindex="-1">D. Weight separation <a class="header-anchor" href="#d-weight-separation" aria-label="Permalink to &quot;D. Weight separation&quot;">​</a></h3><p>A <code>.linnet</code> source file MUST NOT contain raw parameter tensor payloads. Parameters are symbolic declarations. Weight data is bound separately through formats such as SafeTensors and a non-executable binding manifest.</p><h3 id="e-no-hidden-host-execution" tabindex="-1">E. No hidden host execution <a class="header-anchor" href="#e-no-hidden-host-execution" aria-label="Permalink to &quot;E. No hidden host execution&quot;">​</a></h3><p>Parsing, type checking, graph inspection, and parameter-manifest generation MUST NOT execute Python, C++, shell commands, dynamic libraries, network requests, package build scripts, or arbitrary user code.</p><h3 id="f-strict-static-semantics" tabindex="-1">F. Strict static semantics <a class="header-anchor" href="#f-strict-static-semantics" aria-label="Permalink to &quot;F. Strict static semantics&quot;">​</a></h3><p>Shape and dtype compatibility MUST be proven statically whenever the language claims an operation is valid. The compiler MUST NOT silently insert dtype conversions or accept unresolved broadcasting relationships merely because a runtime framework might tolerate them.</p><h3 id="g-single-semantic-frontend" tabindex="-1">G. Single semantic frontend <a class="header-anchor" href="#g-single-semantic-frontend" aria-label="Permalink to &quot;G. Single semantic frontend&quot;">​</a></h3><p>The CLI, language server, formatter, graph visualizer, and backend pipeline MUST consume the same parser and semantic-analysis implementation. Editor tooling MUST NOT reimplement Linnet&#39;s type or shape system in TypeScript, Vimscript, Python, or another language.</p><h3 id="h-source-stability-over-ir-stability" tabindex="-1">H. Source stability over IR stability <a class="header-anchor" href="#h-source-stability-over-ir-stability" aria-label="Permalink to &quot;H. Source stability over IR stability&quot;">​</a></h3><p><code>.linnet</code> source and the language specification are the durable interface. Internal HIR, Core IR, optimizer representations, and plan formats are implementation details until explicitly versioned as public interchange formats.</p><h2 id="_0-3-compilation-model" tabindex="-1">0.3 Compilation model <a class="header-anchor" href="#_0-3-compilation-model" aria-label="Permalink to &quot;0.3 Compilation model&quot;">​</a></h2><p>A conforming implementation conceptually performs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.linnet source</span></span>
<span class="line"><span>    -&gt; syntax tree</span></span>
<span class="line"><span>    -&gt; name/module resolution</span></span>
<span class="line"><span>    -&gt; type + shape analysis</span></span>
<span class="line"><span>    -&gt; typed HIR</span></span>
<span class="line"><span>    -&gt; Core Tensor IR</span></span>
<span class="line"><span>    -&gt; optional optimization</span></span>
<span class="line"><span>    -&gt; backend plan/export/materialization</span></span></code></pre></div><p>A compiler is not required to provide an executor. A conforming frontend can stop after semantic validation or IR generation.</p><h2 id="_0-4-terminology" tabindex="-1">0.4 Terminology <a class="header-anchor" href="#_0-4-terminology" aria-label="Permalink to &quot;0.4 Terminology&quot;">​</a></h2><ul><li><strong>scalar</strong>: a non-tensor value such as <code>f32</code>, <code>i32</code>, or <code>bool</code>.</li><li><strong>tensor</strong>: a value with a statically described rank and symbolic or concrete dimensions.</li><li><strong>dimension expression</strong>: a compile-time integer expression used in tensor shapes.</li><li><strong>shape pack</strong>: a variadic sequence of dimensions, written <code>*S</code> in generic declarations and <code>*s</code> in index notation.</li><li><strong>semantic op</strong>: an <code>op</code> declaration whose identity may be preserved through optimization while its body provides canonical semantics.</li><li><strong>block</strong>: a structural component containing parameters, buffers, sub-blocks, and callable methods.</li><li><strong>entry</strong>: a public execution entry point.</li><li><strong>primitive</strong>: an operation understood directly by Core Tensor IR rather than implemented as a user/library <code>op</code>.</li></ul>`,29)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
